  let catalog=baseCatalog.map(x=>[x.code,x.name,x.params.map(p=>p.label).join(', ')]);
  let catalogDetails=Object.fromEntries(baseCatalog.map(x=>[x.code,x]));
  let catalogLoaded=false;
  const esc=v=>String(v??'').replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','\"':'&quot;'}[c]));
