  async function loadTestCatalog(){
    if(catalogLoaded)return;
    const {data,error}=await client.from('lab_settings').select('test_catalog').eq('tenant_id',profile.tenant_id).maybeSingle();
    if(error)throw error;
    const overrides=data?.test_catalog||{};
    catalogDetails=Object.fromEntries(baseCatalog.map(x=>[x.code,JSON.parse(JSON.stringify(x))]));
    Object.entries(overrides).forEach(([code,v])=>{if(catalogDetails[code])catalogDetails[code]={...catalogDetails[code],...v,params:v.params||catalogDetails[code].params};});
    catalog=Object.values(catalogDetails).map(x=>[x.code,x.name,x.params.map(p=>p.label).join(', ')]);
    catalogLoaded=true;
  }
  function testCards(){
    const q=(document.getElementById('testSearch')?.value||'').toLowerCase().trim();
    return catalog.filter(([c,n,p])=>!q||[c,n,p].join(' ').toLowerCase().includes(q)).map(([c,n,p])=>{
      const d=catalogDetails[c];
      return `<div class="test-card"><div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><span class="code">${esc(c)}</span><button class="ghost small-btn" data-edit-test="${esc(c)}">Edit</button></div><h3>${esc(n)}</h3><p class="muted small-text">${esc(d.category)} · ₹${Number(d.price||0).toFixed(2)}</p><p>${esc(p)}</p></div>`;
    }).join('')||'<div class="panel notice">No tests match your search.</div>';
  }
  function renderTests(){const box=document.getElementById('testCatalogGrid');if(box)box.innerHTML=testCards();}
  async function editTest(code){
    const d=catalogDetails[code];if(!d)return;
    if(!['owner','admin'].includes(profile?.role)){alert('Only owner or admin can edit the test catalog.');return;}
    const name=prompt('Test name:',d.name);if(name===null)return;
    const price=prompt('Test price (₹):',d.price);if(price===null)return;
    const params=d.params.map(p=>({...p}));
    for(const p of params){
      const low=prompt(p.label+' — lower reference value (blank = none):',p.low??'');if(low===null)return;
      const high=prompt(p.label+' — upper reference value (blank = none):',p.high??'');if(high===null)return;
      p.low=low===''?null:Number(low);p.high=high===''?null:Number(high);
      if(Number.isNaN(p.low)||Number.isNaN(p.high)){alert('Reference values must be numeric or blank.');return;}
    }
    const override={name:name.trim()||d.name,price:Number(price),category:d.category,params};
    if(!Number.isFinite(override.price)||override.price<0){alert('Invalid price.');return;}
    const {data:row,error:readErr}=await client.from('lab_settings').select('test_catalog').eq('tenant_id',profile.tenant_id).maybeSingle();if(readErr)throw readErr;
    const merged={...(row?.test_catalog||{}),[code]:override};
    const {error}=await client.from('lab_settings').upsert({tenant_id:profile.tenant_id,test_catalog:merged});if(error)throw error;
    catalogLoaded=false;await loadTestCatalog();renderTests();alert('Test updated successfully.');
  }
    const showLogin=m=>{loginView.classList.remove('hidden');appView.classList.add('hidden');loginMessage.textContent=m||'';};
  const showApp=()=>{loginView.classList.add('hidden');appView.classList.remove('hidden');};
  const canEditPatients=()=>['owner','admin','receptionist'].includes(profile?.role);
  function table(rows,empty='No records found.'){if(!rows.length)return `<div class="empty">${empty}</div>`;const cols=Object.keys(rows[0]).filter(k=>!['tenant_id','id','user_id'].includes(k));return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c.replaceAll('_',' '))}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
  const stat=(label,value,icon)=>`<div class="stat"><div class="stat-icon">${icon}</div><div><div class="stat-value">${value}</div><div class="stat-label">${label}</div></div></div>`;
  async function getProfile(){const {data,error}=await client.from('profiles').select('user_id,tenant_id,email,role,active').eq('user_id',sessionUser.id).single();if(error)throw new Error('Profile not found.');if(!data.active)throw new Error('This laboratory user is inactive.');profile=data;userEmail.textContent=data.email||sessionUser.email||'';userRole.textContent=data.role;}
  async function count(t){const {count:v,error}=await client.from(t).select('*',{count:'exact',head:true});return error?0:v||0;}
  const iconBox=(icon,cls='')=>`<span class="dash-icon ${cls}">${icon}</span>`;
  const kpi=(label,value,meta,icon,cls)=>`<div class="dash-kpi ${cls||''}">${iconBox(icon,cls)}<div class="dash-kpi-body"><span class="dash-kpi-label">${label}</span><strong class="dash-kpi-value">${value}</strong><span class="dash-kpi-meta">${meta}</span></div></div>`;
